54	/** Suggested non-colliding defaults for a brand-new node, computed server-side. */
55	export type NodeDefaults = {
56	  ordinal: number;
57	  subnetPrefix: string;
58	  natChain: string;
59	  ipStart: number;
60	  ipEnd: number;
61	  sshPortStart: number;
62	  sshPortEnd: number;
63	};
64	
65	function Field({
66	  label,
67	  name,
68	  defaultValue,
69	  placeholder,
70	  type = "text",
71	  required = true,
72	  mono = false,
73	  hint,
74	}: {
75	  label: string;
76	  name: string;
77	  defaultValue?: string | number;
78	  placeholder?: string;
79	  type?: string;
80	  required?: boolean;
81	  mono?: boolean;
82	  hint?: string;
83	}) {
84	  return (
85	    <div>
86	      <label className="label">{label}</label>
87	      <input
88	        className={`input ${mono ? "font-mono text-xs" : ""}`}
89	        name={name}
90	        type={type}
91	        defaultValue={defaultValue}
92	        placeholder={placeholder}
93	        required={required}
94	      />
95	      {hint && <p className="mt-1 text-xs text-slate-500">{hint}</p>}
96	    </div>
97	  );
98	}
