100	/** Shared add/edit form. Pass `defaults` for a new node, `node` for editing. */
101	export function NodeForm({ node, defaults }: { node?: NodeValues; defaults?: NodeDefaults }) {
102	  const isEdit = Boolean(node?.id);
103	  const [state, action, pending] = useActionState(isEdit ? updateNode : addNode, {} as { error?: string; ok?: boolean });
104	
105	  const d = node ?? {};
106	  const dflt = defaults;
107	  const [provider, setProvider] = useState<"OVH" | "HETZNER">(d.provider ?? "OVH");
108	
109	  return (
110	    <form action={action} className="space-y-6">
111	      {node?.id && <input type="hidden" name="id" value={node.id} />}
112	
113	      {state?.error && (
114	        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
115	          {state.error}
116	        </div>
117	      )}
118	      {state?.ok && !state?.error && (
119	        <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
120	          Node saved.
121	        </div>
122	      )}
123	
124	      <section>
125	        <h3 className="section-label mb-3">Identity &amp; connection</h3>
126	        <div className="grid gap-4 sm:grid-cols-2">
127	          <Field label="Node name" name="name" defaultValue={d.name} placeholder="node-2" hint="Unique label used in the panel." />
128	          <Field label="Proxmox node (pveNode)" name="pveNode" defaultValue={d.pveNode} placeholder="ns5002570" mono hint="The hostname shown in the Proxmox UI." />
129	          <Field label="API URL" name="apiUrl" defaultValue={d.apiUrl} placeholder="https://1.2.3.4:8006" mono />
130	          <Field label="Public IP" name="publicIp" defaultValue={d.publicIp} placeholder="51.79.162.97" mono hint="The host's public IPv4 — SSH DNAT lands here." />
131	          <Field label="API token ID" name="tokenId" defaultValue={d.tokenId} placeholder="nxeon@pve!platform" mono />
132	          <div>
133	            <label className="label">Provider</label>
134	            <select
135	              className="input"
136	              name="provider"
137	              value={provider}
138	              onChange={(e) => setProvider(e.target.value as "OVH" | "HETZNER")}
