153	          </div>
154	          <Field
155	            label="Provider server ID"
156	            name="providerServerId"
157	            defaultValue={d.providerServerId ?? ""}
158	            required={false}
159	            placeholder={provider === "HETZNER" ? "2769362 (Hetzner server number)" : "ns5002569.ip-51-79-162.net"}
160	            mono
161	            hint="OVH's service name or Hetzner's server number — needed for that node's own dedicated-IP pool."
162	          />
163	          <Field
164	            label="API token secret"
165	            name="tokenSecret"
166	            defaultValue=""
