265	/** Live health-check button that surfaces the result inline. */
266	export function TestNodeButton({ id, compact = false }: { id: string; compact?: boolean }) {
267	  const [pending, start] = useTransition();
268	  const [result, setResult] = useState<TestNodeResult | null>(null);
269	
270	  const run = () => start(async () => setResult(await testNode(id)));
271	
272	  if (compact) {
273	    return (
274	      <button className="btn-secondary py-1.5" disabled={pending} onClick={run} title="Health check">
275	        {pending ? "Testing…" : "Test"}
276	      </button>
277	    );
278	  }
279	
280	  return (
281	    <div className="space-y-3">
282	      <button className="btn-secondary" disabled={pending} onClick={run}>
283	        {pending ? "Contacting Proxmox…" : "Run health check"}
284	      </button>
285	      {result && (
286	        <div
287	          className={`rounded-xl border px-4 py-3 text-sm ${
288	            result.ok
289	              ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-200"
290	              : "border-red-500/30 bg-red-500/10 text-red-300"
