297	                <div className="flex justify-between gap-2">
298	                  <dt className="text-slate-500">Uptime</dt>
299	                  <dd>{Math.floor(result.uptimeSec / 86400)}d {Math.floor((result.uptimeSec % 86400) / 3600)}h</dd>
300	                </div>
301	              )}
302	              {result.ramTotal != null && (
303	                <div className="flex justify-between gap-2">
304	                  <dt className="text-slate-500">RAM used</dt>
305	                  <dd>
306	                    {((result.ramUsed ?? 0) / 1024 ** 3).toFixed(1)}/{(result.ramTotal / 1024 ** 3).toFixed(0)} GB
307	                  </dd>
308	                </div>
309	              )}
310	              {result.cpu != null && (
311	                <div className="flex justify-between gap-2">
312	                  <dt className="text-slate-500">CPU</dt>
