326	      )}
327	      {result?.agentOk !== undefined && (
328	        <div
329	          className={`rounded-xl border px-4 py-3 text-sm ${
330	            result.agentOk
331	              ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-200"
332	              : "border-amber-500/30 bg-amber-500/10 text-amber-300"
333	          }`}
334	        >
335	          <p className="font-medium">Node-agent: {result.agentOk ? "reachable" : "unreachable"}</p>
336	          {result.agentMessage && <p className="mt-1 text-xs opacity-90">{result.agentMessage}</p>}
337	        </div>
