356	/**
357	 * Inline "type a dollar amount, it saves on blur" field for `Node.monthlyCostCents`
358	 * — the same "commit immediately via a server action, no separate save-then-navigate
359	 * step" convention as EnableToggle/StatusSelect above, just for a free-typed number
360	 * instead of a button/select. Dollars in the input, cents on the wire (mirrors the
361	 * amount/step="0.01" convention RefundControls/GiftCodeControls already use).
362	 * Blank clears the field back to "not set" — see setNodeMonthlyCost's own doc.
363	 */
364	export function NodeCostInput({ id, initialCents }: { id: string; initialCents: number | null }) {
365	  const asDollars = (c: number | null) => (c != null ? (c / 100).toFixed(2) : "");
366	  const [value, setValue] = useState(asDollars(initialCents));
367	  const [pending, start] = useTransition();
368	  const [err, setErr] = useState<string | null>(null);
369	  const [saved, setSaved] = useState(false);
370	  const lastSaved = asDollars(initialCents);
371	
372	  const save = () => {
373	    if (value === lastSaved) return;
374	    setErr(null);
375	    start(async () => {
376	      const res = await setNodeMonthlyCost(id, value);
377	      if (res?.error) setErr(res.error);
378	      else {
379	        setSaved(true);
380	        setTimeout(() => setSaved(false), 1500);
381	      }
382	    });
383	  };
384	
385	  return (
386	    <div>
387	      <div className="flex items-center gap-1">
388	        <span className="text-xs text-slate-500">$</span>
389	        <input
390	          className="input w-20 py-1 text-xs"
391	          type="number"
392	          step="0.01"
393	          min="0"
394	          placeholder="not set"
395	          value={value}
396	          disabled={pending}
397	          onChange={(e) => setValue(e.target.value)}
398	          onBlur={save}
399	          onKeyDown={(e) => {
400	            if (e.key === "Enter") e.currentTarget.blur();
401	          }}
402	        />
403	        <span className="text-[10px] text-slate-500">/mo</span>
404	      </div>
405	      {pending && <p className="mt-0.5 text-[10px] text-slate-500">saving…</p>}
406	      {saved && !pending && <p className="mt-0.5 text-[10px] text-emerald-400">saved</p>}
407	      {err && <p className="mt-0.5 text-[10px] text-red-400">{err}</p>}
408	    </div>
409	  );
410	}
