430	export function DeleteNodeButton({
431	  id,
432	  name,
433	  serverCount,
434	  isPrimary,
435	}: {
436	  id: string;
437	  name: string;
438	  serverCount: number;
439	  isPrimary: boolean;
440	}) {
441	  const router = useRouter();
442	  const [pending, start] = useTransition();
443	  const [err, setErr] = useState<string | null>(null);
444	
445	  const disabled = isPrimary || serverCount > 0;
446	  const reason = isPrimary
447	    ? "The primary node cannot be deleted."
448	    : serverCount > 0
449	      ? `${serverCount} server(s) still assigned — migrate them first.`
450	      : undefined;
451	
452	  return (
453	    <div>
454	      <button
455	        className="btn-danger py-1.5"
456	        disabled={pending || disabled}
457	        title={reason}
458	        onClick={() => {
459	          if (!window.confirm(`Delete node "${name}"? This only removes the DB record, not the physical host.`)) return;
460	          start(async () => {
461	            const res = await deleteNode(id);
462	            if (res?.error) setErr(res.error);
463	            else router.push("/admin/nodes");
464	          });
465	        }}
466	      >
467	        {pending ? "Deleting…" : "Delete node"}
468	      </button>
469	      {reason && <p className="mt-1 text-xs text-slate-500">{reason}</p>}
470	      {err && <p className="mt-1 text-xs text-red-400">{err}</p>}
471	    </div>
472	  );
473	}
