32	/**
33	 * IP allow-list gate for /admin. `allowed_admin_ips` is a comma-separated list of
34	 * literal IPs; empty = no restriction. Fails OPEN (allows) when the list has no
35	 * parseable entries or the requester IP can't be determined, so a bad value can
36	 * never lock every admin out — only an exact match is ever enforced.
37	 * Returns true when access should be REFUSED.
38	 */
39	async function adminIpBlocked(): Promise<boolean> {
40	  const raw = await getSetting("allowed_admin_ips", "");
41	  const entries = raw.split(",").map((s) => s.trim()).filter(Boolean);
42	  if (entries.length === 0) return false; // no restriction configured
43	  const valid = entries.filter(isPlainIp);
44	  if (valid.length === 0) {
45	    console.warn("[admin-ip] allowed_admin_ips is set but has no valid IPs; failing open:", raw);
46	    return false; // malformed -> fail open
47	  }
48	  const hdrs = await headers();
49	  // Trust nginx's X-Real-IP ($remote_addr), which the client cannot forge. Fall
50	  // back to the LAST X-Forwarded-For hop (the one our proxy appended), never the
51	  // client-supplied leftmost entry.
52	  const xff = (hdrs.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
53	  const ip = hdrs.get("x-real-ip")?.trim() || xff[xff.length - 1] || "";
54	  if (!ip) {
55	    console.warn("[admin-ip] could not determine requester IP; failing open");
56	    return false;
57	  }
58	  return !valid.includes(ip);
59	}
