81	export default async function AdminLayout({ children }: { children: React.ReactNode }) {
82	  // Wrong host (e.g. public nxeon.cloud) → 404, so /admin isn't reachable there.
83	  if (await adminHostBlocked()) notFound();
84	
85	  // The dedicated login page (app/admin/login) is the one public, unauthenticated
86	  // route under /admin — render it bare (no Shell, no auth requirement below) so
87	  // a signed-out visitor doesn't hit `redirect("/admin/login")` on the page that
88	  // IS /admin/login. middleware.ts injects x-pathname since a Server Component
89	  // has no other way to read the current path. Still honors the IP allowlist —
90	  // a locked-out network shouldn't see the login form either.
91	  const pathname = (await headers()).get("x-pathname") ?? "";
92	  if (pathname === "/admin/login") {
93	    if (await adminIpBlocked()) return <RestrictedNetwork />;
94	    return <>{children}</>;
95	  }
96	
97	  const user = await realUser();
98	  if (!user) redirect("/admin/login");
99	  if (!isStaff(user.role)) redirect("/dashboard");
100	  const imp = await impersonating();
101	  if (imp) redirect("/dashboard"); // exit impersonation before using admin tools
102	
103	  // IP allow-list: refuse admin access from an IP that isn't explicitly allowed.
104	  if (await adminIpBlocked()) return <RestrictedNetwork />;
105	
106	  // Staff 2FA enforcement: when enabled, staff without TOTP must set it up before
107	  // using admin tools. Redirect (don't hard-fail) to their security settings so
108	  // they can enroll, then come back.
109	  if ((await getSettingBool("enforce_staff_2fa", false)) && !user.totpEnabled) {
