114	  // consoles are internal/experimental — their nav sections are hidden by default
115	  // and only surface when the operator flips the flag. The pages/routes are never
116	  // removed; this only drops the nav entry, its sub-tabs and its ⌘K entries.
117	  const [showAgency, showAds] = await Promise.all([
118	    getSettingBool("feature_admin_agency", false),
119	    getSettingBool("feature_admin_ads", false),
