129	  // Filter every entry's members down to what this role can access, drop entries
130	  // that end up empty, then drop sections that end up empty. An entry always
131	  // links to (and its sub-tab bar always starts at) its first *accessible*
132	  // member, so no role is ever handed a link that just bounces it to /admin.
133	  const visibleSections = navSections.map((section) => ({
