154	
155	  // Attention-count badges for the sidebar. Each count fails soft (→ 0) so a
156	  // missing model/table can never break the admin layout.
157	  const soft = (p: Promise<number>) => p.catch(() => 0);
158	  const [chatUnread, ticketsAwaiting, dmsAwaiting, abuseOpen, feedbackNew, improvementsProposed, coldEmailUnread] = await Promise.all([
159	    // Live chat: conversations flagged unread for agents (same "needs a reply"
160	    // signal the chat inbox sorts/counts by — ChatConversation.unreadForAgent).
161	    soft(db.chatConversation.count({ where: { unreadForAgent: true } })),
162	    // Support desk: tickets awaiting a staff reply (open + customer replies),
163	    // matching the "Awaiting staff" stat on /admin/support.
164	    soft(db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })),
165	    // Direct messages: DM threads with a customer reply staff hasn't seen yet
166	    // (StaffDm.unreadForStaff) — same "needs a reply" signal as live chat.
167	    soft(dmDb.staffDm.count({ where: { unreadForStaff: true } })),
168	    // Abuse queue: alerts still OPEN.
169	    soft(db.abuseAlert.count({ where: { status: "OPEN" } })),
170	    // Feedback: new (untriaged) reports.
171	    soft(db.feedback.count({ where: { status: "NEW" } })),
172	    // Improvements board: proposals awaiting the owner's approve/decline.
173	    soft(db.improvement.count({ where: { status: "PROPOSED" } })),
174	    // Cold email: unread replies in the reply inbox (Conversation.unread), same
175	    // "needs a reply" signal as live chat above.
176	    soft(db.conversation.count({ where: { unread: true } })),
177	  ]);
178	
179	  // Per-route attention counts, unchanged in meaning from the flat sidebar.
180	  const badges: Record<string, number> = {
181	    "/admin/chat": chatUnread,
182	    "/admin/support": ticketsAwaiting,
183	    "/admin/dms": dmsAwaiting,
184	    "/admin/abuse": abuseOpen,
185	    "/admin/feedback": feedbackNew,
186	    "/admin/improvements": improvementsProposed,
187	    "/admin/coldemail/inbox": coldEmailUnread,
188	  };
189	  // Build the sidebar: one icon'd row per top-level ENTRY, grouped into labelled
190	  // sections. Secondary members ride along as `children` — the sidebar never
191	  // expands them (they're the page's sub-tabs), but they keep the parent row
192	  // highlighted while you're on one and keep ⌘K able to reach every route.
193	  // Attention counts ROLL UP: an entry shows the sum of its members' badges, and
194	  // <AdminSubTabs /> repeats each member's own count on its tab.
195	  const nav: NavSection[] = visibleSections.map((section) => ({
196	    key: section.key,
197	    label: section.label,
198	    items: section.entries.map((entry) => {
199	      const rollup = entry.tabs.reduce((sum, tab) => sum + (badges[tab.href] ?? 0), 0);
200	      return {
201	        label: entry.label,
202	        href: entry.tabs[0].href,
203	        icon: entry.icon,
204	        badge: rollup > 0 ? rollup : undefined,
205	        children: entry.tabs.map((tab) => ({
206	          label: tab.label,
207	          href: tab.href,
208	          badge: badges[tab.href] > 0 ? badges[tab.href] : undefined,
209	        })),
210	      };
211	    }),
212	  }));
213	
214	  return (
215	    <Shell
216	      nav={nav}
217	      tag="ops"
218	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
219	      notifications={notifications.map((n) => ({
220	        id: n.id,
221	        title: n.title,
222	        body: n.body,
223	        href: n.href,
224	        readAt: n.readAt ? n.readAt.toISOString() : null,
225	        createdAt: n.createdAt.toISOString(),
226	      }))}
227	    >
228	      {/* Sub-navigation for the consolidated entries, mounted once here so every
229	          grouped page gets its tab bar without per-page wiring. Renders nothing
230	          for single-member entries. */}
231	      <AdminSubTabs badges={badges} allowed={allowedHrefs} />
232	      {/* Browser sound + Web Notification when a new live-chat message arrives
233	          while an admin tab is open. Self-contained + defensive; renders null. */}
234	      <AdminChatNotifier />
235	      {children}
236	    </Shell>
237	  );
238	}
