/**
 * Information architecture for the admin ops portal.
 *
 * The sidebar shows one TOP-LEVEL ENTRY per destination cluster (26 of them,
 * across 10 sections as of the 2026-08-26 Accounting addition — Content moved
 * into Marketing, Mail split out into its own top-level section, System
 * renamed to Settings). Every entry
 * carries an icon and links to `tabs[0]`; its remaining members are reached
 * from a horizontal sub-tab bar rendered once by the admin layout via
 * <AdminSubTabs /> (see components/admin/SubTabs.tsx).
 *
 * That keeps all ~85 admin routes exactly two clicks away while the sidebar
 * stays short enough to fit a 1080p laptop with no scrolling — the previous
 * shapes (6 collapsed group headers, then 41 flat rows) failed at one end or
 * the other. No route was moved or removed: every URL that worked before still
 * resolves, it is simply reached through its parent entry's tab bar now.
 *
 * This module is intentionally free of any server-only imports so it can be
 * consumed by both the server admin layout (for role filtering + badge
 * roll-up) and the client sub-tab bar.
 */

export type SubTabItem = { label: string; href: string };

export type AdminEntry = {
  /** Stable key for the entry. */
  key: string;
  /** Sidebar label. */
  label: string;
  /** Shell icon name (see the `icons` map in components/portal/Shell.tsx). */
  icon: string;
  /**
   * Members, in display order. `tabs[0]` is the entry's landing page and the
   * href the sidebar links to. A single-member entry renders no tab bar.
   */
  tabs: SubTabItem[];
};

