import { useMemo, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import type { ReactNode } from "react";

export type BulkColumn = { header: ReactNode; className?: string };
export type BulkRow = { id: string; cells: ReactNode[]; selectable?: boolean };
export type BulkAction = {
  label: string;
  /** Server action invoked with the selected row ids. */
  run: (ids: string[]) => Promise<unknown>;
  /** Confirmation prompt shown before running (skip when omitted). */
  confirm?: string;
  danger?: boolean;
};

/**
 * A self-contained, selectable admin table. The parent (a Server Component)
 * maps its data into `columns` + `rows` (cells may be arbitrary React nodes such
 * as <Link>s) and passes an `exportHref` and optional bulk `actions`. Selection
 * state, the select-all header checkbox and the floating action bar all live
 * here on the client; the export link points at the CSV route.
 */
export function BulkTable({
  columns,
  rows,
  exportHref,
  actions = [],
  minWidth = 720,
  empty = "Nothing to show.",
}: {
  columns: BulkColumn[];
  rows: BulkRow[];
  exportHref?: string;
  actions?: BulkAction[];
  minWidth?: number;
  empty?: string;
}) {
  const router = useRouter();
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);

  const selectableIds = useMemo(
    () => rows.filter((r) => r.selectable !== false).map((r) => r.id),
    [rows]
  );
  const allSelected = selectableIds.length > 0 && selectableIds.every((id) => selected.has(id));
  const someSelected = selected.size > 0;

  const toggle = (id: string) =>
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });

  const toggleAll = () =>
    setSelected(allSelected ? new Set() : new Set(selectableIds));

  const runAction = (action: BulkAction) => {
    if (action.confirm && !window.confirm(action.confirm)) return;
    const ids = [...selected];
    setMsg(null);
    start(async () => {
      try {
        await action.run(ids);
        setSelected(new Set());
        setMsg(`${action.label}: ${ids.length} row${ids.length === 1 ? "" : "s"} done.`);
        router.refresh();
      } catch (e) {
        setMsg(e instanceof Error ? e.message : "Action failed");
      }
    });
  };

  return (
    <div>
      {/* Action bar */}

